('bmlt-parasite-mcq-013','BMLT','BMLT NHPC Licensing','mcq','free',412,'{"question":"Hookworm infection commonly occurs when larvae:","translation":"Hookworm संक्रमण सामान्यतः कसरी हुन्छ?","options":["Penetrate skin","Are inhaled as cysts","Enter through mosquito bite","Are injected by tick"],"correctIndex":0,"explanation":"Filariform larvae can penetrate exposed skin, often bare feet.","explanationNe":"Filariform larva छालाबाट, प्रायः नाङ्गो खुट्टाबाट प्रवेश गर्छ।","topic":"Medical Parasitology"}'::jsonb,true),
