('bmlt-parasite-mock-023','BMLT','BMLT NHPC Licensing','mock','free',522,'{"question":"The definitive host of a parasite is the host in which:","translation":"Definitive host भन्नाले के बुझिन्छ?","options":["Sexual reproduction or adult stage occurs","Only eggs are ingested","No development occurs","The parasite is always absent"],"correctIndex":0,"explanation":"Definitive hosts harbor the adult or sexual reproductive stage.","explanationNe":"Adult वा sexual reproductive stage रहने host definitive host हो।","topic":"Medical Parasitology"}'::jsonb,true),
('bmlt-parasite-mock-024','BMLT','BMLT NHPC Licensing','mock','free',523,'{"question":"A parasite''s reservoir host is one that:","translation":"Reservoir host को भूमिका के हो?","options":["Maintains the parasite and may serve as a source of infection","Cannot become infected","Is always the vector","Only carries antibodies"],"correctIndex":0,"explanation":"Reservoir hosts maintain infection in nature and can contribute to transmission.","explanationNe":"Reservoir host ले प्रकृतिमा parasite कायम राखेर संक्रमणको स्रोत बन्न सक्छ।","topic":"Medical Parasitology"}'::jsonb,true),
('bmlt-parasite-mock-025','BMLT','BMLT NHPC Licensing','mock','free',524,'{"question":"Which practice helps prevent intestinal parasitic infections?","translation":"आन्द्राका parasite संक्रमण रोक्न कुन उपाय उपयोगी हुन्छ?","options":["Handwashing and safe food/water","Walking barefoot in endemic soil","Eating raw contaminated vegetables","Open defecation"],"correctIndex":0,"explanation":"Hygiene, sanitation, safe water and properly cooked food reduce transmission.","explanationNe":"हात धुने, सरसफाइ, सुरक्षित पानी र राम्रोसँग पकाएको खाना उपयोगी हुन्छ।","topic":"Medical Parasitology"}'::jsonb,true);
